const lessons=[{"sentences":[{"speaker":"A","text":"We need to discuss how we should share this small community garden.","position":1,"audioStartSeconds":0,"audioEndSeconds":3.999833333333333},{"speaker":"B","text":"I think we should divide it into equal sections so everyone gets a fair amount of space.","position":2,"audioStartSeconds":4.199833333333333,"audioEndSeconds":9.655875},{"speaker":"A","text":"That sounds reasonable although some families might need more room for tall vegetables.","position":3,"audioStartSeconds":9.855875,"audioEndSeconds":15.256125},{"speaker":"B","text":"If someone wants extra space they can share their harvest with neighbours in return.","position":4,"audioStartSeconds":15.456125,"audioEndSeconds":20.418208333333332},{"speaker":"A","text":"What about the tools and the watering equipment that we bought together last spring?","position":5,"audioStartSeconds":20.61820833333333,"audioEndSeconds":25.399166666666666},{"speaker":"B","text":"We can keep them in the small wooden shed and create a weekly borrowing schedule.","position":6,"audioStartSeconds":25.599166666666665,"audioEndSeconds":30.444541666666666},{"speaker":"A","text":"When should we finish planting everything because the rainy season is starting soon?","position":7,"audioStartSeconds":30.644541666666665,"audioEndSeconds":35.55433333333333},{"speaker":"B","text":"We must finish all the planting before next weekend if we want healthy plants.","position":8,"audioStartSeconds":35.754333333333335,"audioEndSeconds":40.68991666666667},{"speaker":"A","text":"Should we also set up a composting area near the back fence to recycle waste?","position":9,"audioStartSeconds":40.889916666666664,"audioEndSeconds":45.928583333333336},{"speaker":"B","text":"That is a brilliant idea because rich soil will help all our vegetables grow much faster.","position":10,"audioStartSeconds":46.12858333333333,"audioEndSeconds":51.61825},{"speaker":"A","text":"Who is going to remind everyone about the new rules and the watering timetable?","position":11,"audioStartSeconds":51.81825,"audioEndSeconds":56.52183333333333},{"speaker":"B","text":"I can send a message to our neighbourhood group chat this evening.","position":12,"audioStartSeconds":56.721833333333336,"audioEndSeconds":60.806875},{"speaker":"A","text":"Thank you for organizing this because I was worried about managing the plot alone.","position":13,"audioStartSeconds":61.006875,"audioEndSeconds":65.92954166666667},{"speaker":"B","text":"Working together makes everything much easier and more enjoyable for us all.","position":14,"audioStartSeconds":66.12954166666667,"audioEndSeconds":71.10045833333334},{"speaker":"A","text":"Let us meet tomorrow morning to measure the plots and start digging.","position":15,"audioStartSeconds":71.30045833333334,"audioEndSeconds":75.558}],"questions":[{"prompt":"What is the main purpose of the conversation?","options":["To plan a neighbourhood party.","To divide a community garden.","To buy new gardening tools."],"answer":"B","evidenceSentence":1,"evidence":"share this small community garden","explanation":"Mục đích chính của đoạn hội thoại là thảo luận cách chia sẻ khu vườn cộng đồng nhỏ."},{"prompt":"Why does Speaker B suggest dividing the garden into equal sections?","options":["To ensure everyone gets fair space.","To make room for tall vegetables.","To build a wooden shed there."],"answer":"A","evidenceSentence":2,"evidence":"everyone gets a fair amount of space","explanation":"Speaker B đề xuất chia đều để mọi người đều có khoảng không gian công bằng."},{"prompt":"What does Speaker A point out about tall vegetables?","options":["They need less water.","They grow during winter.","Some families might need more room."],"answer":"C","evidenceSentence":3,"evidence":"some families might need more room for tall vegetables","explanation":"Speaker A lưu ý rằng một số gia đình có thể cần nhiều chỗ hơn cho các loại rau cao."},{"prompt":"Where will they store the shared tools?","options":["In a small wooden shed.","Near the back fence.","Inside the neighbourhood hall."],"answer":"A","evidenceSentence":6,"evidence":"keep them in the small wooden shed","explanation":"Các dụng cụ chung sẽ được cất giữ trong một nhà kho gỗ nhỏ."},{"prompt":"When must they finish planting according to Speaker B?","options":["Tomorrow morning.","Before next weekend.","Next spring."],"answer":"B","evidenceSentence":8,"evidence":"finish all the planting before next weekend","explanation":"Speaker B cho biết họ phải hoàn thành việc trồng trọt trước cuối tuần tới."},{"prompt":"What will Speaker B do this evening?","options":["Measure the garden plots.","Build a composting area.","Send a message to the group chat."],"answer":"C","evidenceSentence":12,"evidence":"send a message to our neighbourhood group chat this evening","explanation":"Speaker B sẽ gửi tin nhắn vào nhóm chat của khu phố vào tối nay để nhắc nhở mọi người."}]}];const cards=[...document.querySelectorAll('article')];let stopping=null,stoppingAudio=null;
    document.addEventListener('play',event=>{if(event.target.tagName!=='AUDIO')return;document.querySelectorAll('audio').forEach(a=>{if(a!==event.target)a.pause()})},true);
    document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{let count=0;cards.forEach(c=>{c.hidden=button.dataset.filter!=='ALL'&&c.dataset.goal!==button.dataset.filter;if(!c.hidden)count++;else c.querySelector('audio').pause()});document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));document.querySelector('#filter-status').textContent='Đang hiển thị '+count+' bài.'});
    const normal=value=>value.trim().toLowerCase().replace(/\s+/g,' ');
    document.querySelectorAll('[data-check]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.check);let score=0;lessons[i].questions.forEach((q,n)=>{const value=normal(document.getElementById('answer-'+i+'-'+n).value);if([q.answer,...(q.accepted||[])].some(a=>normal(a)===value))score++});document.getElementById('result-'+i).textContent=score+'/'+lessons[i].questions.length+' câu đúng. Mở phần đáp án để xem giải thích.'});
    document.querySelectorAll('[data-segment]').forEach(button=>button.onclick=async()=>{if(stopping)stopping();const [i,n]=button.dataset.segment.split(',').map(Number),audio=cards[i].querySelector('audio'),s=lessons[i].sentences[n];audio.currentTime=s.audioStartSeconds;const stop=()=>{stopping=null;stoppingAudio=null;audio.removeEventListener('timeupdate',check);audio.pause()},check=()=>{if(audio.currentTime>=s.audioEndSeconds)stop()};stopping=stop;stoppingAudio=audio;audio.addEventListener('timeupdate',check);try{await audio.play()}catch(_){stop();document.getElementById('result-'+i).textContent='Không phát được audio. Hãy dùng nút tải WAV để nghe.'}});
    document.querySelectorAll('audio').forEach(audio=>audio.addEventListener('pause',()=>{if(audio.paused&&stoppingAudio===audio&&stopping)stopping()}));
const authStatus=document.querySelector('#auth-status');
async function initializeAudio(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin'});
  if(response.status===401){authStatus.hidden=false;authStatus.innerHTML='Đăng nhập để nghe audio. <a href="/login?next=%2Fcatalog%3Fgoal%3DALL">Đăng nhập</a> rồi mở bài từ thư viện bằng nút “Nghe toàn bài & làm câu hỏi”.';return}
  if(!response.ok)throw Error('account');
  document.querySelectorAll('audio').forEach(audio=>{audio.src=audio.dataset.src;audio.preload='none';audio.hidden=false});
  document.querySelectorAll('[data-segment]').forEach(button=>button.disabled=false);
  document.querySelectorAll('a[download]').forEach(link=>link.hidden=false);
 }catch(_){authStatus.hidden=false;authStatus.textContent='Không kiểm tra được đăng nhập. Hãy tải lại trang để thử lại.'}
}
initializeAudio();
